#include <bits/stdc++.h>
using namespace std;

class Solution {
    unordered_map<int, int> memo;
    int solve(int n) {
        if (n <= 1) return n;
        auto it = memo.find(n);
        if (it != memo.end()) return it->second;
        return memo[n] = 1 + min(n % 2 + solve(n / 2),
                                 n % 3 + solve(n / 3));
    }
public:
    int minDays(int n) { return solve(n); }
};
